package net.civeira.phylax.features.oauth.scopes.application;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.util.List;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.mockito.ArgumentCaptor;

import net.civeira.phylax.features.oauth.scopes.domain.ScopePermission;
import net.civeira.phylax.features.oauth.scopes.domain.gateway.ScopesConsentGateway;

class ScopesConsentUsecaseTest {

  private ScopesConsentGateway gateway;
  private ScopesConsentUsecase usecase;

  @BeforeEach
  void setUp() {
    gateway = mock(ScopesConsentGateway.class);
    usecase = new ScopesConsentUsecase(gateway);
  }

  // T2.4.1
  @Test
  void pendingScopes_normalizesAndDeduplicates() {
    when(gateway.pendingScopes(eq("test-tenant"), eq("alice@example.com"), eq("test-client"),
        eq(List.of("openid", "profile")))).thenReturn(List.of());

    usecase.pendingScopes("test-tenant", "alice@example.com", "test-client",
        "openid openid profile");

    @SuppressWarnings("unchecked")
    ArgumentCaptor<List<String>> captor = ArgumentCaptor.forClass(List.class);
    verify(gateway).pendingScopes(eq("test-tenant"), eq("alice@example.com"), eq("test-client"),
        captor.capture());

    List<String> normalized = captor.getValue();
    assertEquals(2, normalized.size());
    assertTrue(normalized.contains("openid"));
    assertTrue(normalized.contains("profile"));
    assertEquals(normalized.size(), normalized.stream().distinct().count());
  }

  // T2.4.2
  @Test
  void pendingScopes_emptyScopeString_callsGatewayWithEmptyList() {
    when(gateway.pendingScopes(eq("test-tenant"), eq("alice@example.com"), eq("test-client"),
        eq(List.of()))).thenReturn(List.of());

    List<ScopePermission> result =
        usecase.pendingScopes("test-tenant", "alice@example.com", "test-client", "");

    assertTrue(result.isEmpty());
    verify(gateway).pendingScopes("test-tenant", "alice@example.com", "test-client", List.of());
  }

  // T2.4.3
  @Test
  void storeAcceptedScopes_delegatesNormalizedListToGateway() {
    usecase.storeAcceptedScopes("test-tenant", "alice@example.com", "test-client",
        "openid profile email");

    @SuppressWarnings("unchecked")
    ArgumentCaptor<List<String>> captor = ArgumentCaptor.forClass(List.class);
    verify(gateway).storeAcceptedScopes(eq("test-tenant"), eq("alice@example.com"),
        eq("test-client"), captor.capture());

    List<String> scopes = captor.getValue();
    assertEquals(3, scopes.size());
    assertTrue(scopes.contains("openid"));
    assertTrue(scopes.contains("profile"));
    assertTrue(scopes.contains("email"));
  }
}
